import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ServiceRegistryService } from '../../services/service-registry.service';
import { ParameterLibraryService } from '../../services/parameter-library.service';
import { ServiceDefinition, ServiceParameter } from '../../models/service-definition.model';
import { HelpModal } from '../../components/help-modal/help-modal';

@Component({
  selector: 'app-service-manager',
  standalone: true,
  imports: [FormsModule, HelpModal],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './service-manager.html',
  styleUrl: './service-manager.scss'
})
export class ServiceManager {
  readonly registry = inject(ServiceRegistryService);
  readonly paramLibrary = inject(ParameterLibraryService);

  readonly services = this.registry.allServices;
  readonly parameterTypes = this.paramLibrary.allTypes;

  /** Currently selected service for viewing/editing */
  selectedServiceId = signal<string | null>(null);

  /** Whether we're in "add new" mode */
  addingNew = signal(false);

  /** New service form data */
  newService = signal<Partial<ServiceDefinition>>({
    programName: '',
    displayName: '',
    description: '',
    parameters: []
  });

  /** New parameter being added */
  newParam = signal<Partial<ServiceParameter>>({
    position: 1,
    parameterTypeKey: '',
    required: false
  });

  selectService(id: string): void {
    this.selectedServiceId.set(id);
    this.addingNew.set(false);
  }

  getSelectedService(): ServiceDefinition | undefined {
    const id = this.selectedServiceId();
    return id ? this.registry.getService(id) : undefined;
  }

  startAddNew(): void {
    this.addingNew.set(true);
    this.selectedServiceId.set(null);
    this.newService.set({
      programName: '',
      displayName: '',
      description: '',
      parameters: []
    });
  }

  cancelAddNew(): void {
    this.addingNew.set(false);
  }

  addParameterToNew(): void {
    const np = this.newParam();
    if (!np.parameterTypeKey) return;

    this.newService.update(svc => ({
      ...svc,
      parameters: [
        ...(svc.parameters || []),
        {
          position: (svc.parameters?.length || 0) + 1,
          parameterTypeKey: np.parameterTypeKey!,
          required: np.required || false
        }
      ]
    }));

    this.newParam.set({ position: 1, parameterTypeKey: '', required: false });
  }

  removeParameterFromNew(index: number): void {
    this.newService.update(svc => ({
      ...svc,
      parameters: (svc.parameters || [])
        .filter((_, i) => i !== index)
        .map((p, i) => ({ ...p, position: i + 1 }))
    }));
  }

  saveNewService(): void {
    const svc = this.newService();
    if (!svc.programName || !svc.displayName) return;

    const service: ServiceDefinition = {
      id: svc.programName!.toLowerCase().replace(/\s+/g, '_'),
      programName: svc.programName!,
      displayName: svc.displayName!,
      description: svc.description || '',
      parameters: svc.parameters as ServiceParameter[] || []
    };

    this.registry.saveService(service);
    this.addingNew.set(false);
    this.selectedServiceId.set(service.id);
  }

  removeService(id: string): void {
    this.registry.deleteService(id);
    if (this.selectedServiceId() === id) {
      this.selectedServiceId.set(null);
    }
  }

  resetService(id: string): void {
    this.registry.resetService(id);
  }

  exportServices(): void {
    const bundle = {
      version: 2,
      parameterTypes: this.paramLibrary.exportAllTypes(),
      services: this.registry.allServices()
    };
    const json = JSON.stringify(bundle, null, 2);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'dwsv-bundle.json';
    a.click();
    URL.revokeObjectURL(url);
  }

  importServices(event: Event): void {
    const file = (event.target as HTMLInputElement).files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(reader.result as string);

        if (data.version) {
          // New bundle format: import parameter types first, then services
          const paramResult = this.paramLibrary.importTypes(data.parameterTypes || []);
          const serviceResult = this.registry.importServices(JSON.stringify(data.services || []));
          this.importMessage.set(
            `Imported ${serviceResult.imported} services, ${paramResult.imported} parameters, skipped ${serviceResult.skipped + paramResult.skipped}`
          );
        } else if (Array.isArray(data)) {
          // Old format: array of services only (backward compatible)
          const result = this.registry.importServices(JSON.stringify(data));
          this.importMessage.set(`Imported ${result.imported}, skipped ${result.skipped} (duplicate IDs)`);
        } else {
          this.importMessage.set('Error: Unrecognized file format');
        }

        setTimeout(() => this.importMessage.set(null), 3000);
      } catch {
        this.importMessage.set('Error: Invalid JSON file');
        setTimeout(() => this.importMessage.set(null), 3000);
      }
    };
    reader.readAsText(file);
  }

  importMessage = signal<string | null>(null);

  /** Whether the help modal is open */
  helpOpen = signal(false);

  /** Update a field on the new service form */
  updateNewServiceField(field: string, value: any): void {
    this.newService.update(s => ({ ...s, [field]: value }));
  }

  /** Update a field on the new parameter form */
  updateNewParamField(field: string, value: any): void {
    this.newParam.update(p => ({ ...p, [field]: value }));
  }

  /** Get the label for a parameter type key */
  getParamTypeLabel(key: string): string {
    return this.paramLibrary.getType(key)?.label || key;
  }

  /** Update a field on the selected service and save */
  updateServiceField(field: string, value: any): void {
    const svc = this.getSelectedService();
    if (!svc) return;
    const updated = { ...svc, [field]: value };
    this.registry.saveService(updated);
  }

  /** Add a parameter to the selected service */
  addParameterToService(): void {
    const svc = this.getSelectedService();
    const np = this.newParam();
    if (!svc || !np.parameterTypeKey) return;

    const updated = {
      ...svc,
      parameters: [
        ...svc.parameters,
        {
          position: svc.parameters.length + 1,
          parameterTypeKey: np.parameterTypeKey!,
          required: np.required || false
        }
      ]
    };
    this.registry.saveService(updated);
    this.newParam.set({ position: 1, parameterTypeKey: '', required: false });
  }

  /** Remove a parameter from the selected service */
  removeParameterFromService(index: number): void {
    const svc = this.getSelectedService();
    if (!svc) return;

    const updated = {
      ...svc,
      parameters: svc.parameters
        .filter((_, i) => i !== index)
        .map((p, i) => ({ ...p, position: i + 1 }))
    };
    this.registry.saveService(updated);
  }

  /** Update the default value override on a parameter */
  updateParameterDefault(index: number, value: string): void {
    const svc = this.getSelectedService();
    if (!svc) return;

    const params = [...svc.parameters];
    params[index] = {
      ...params[index],
      defaultValueOverride: value || undefined
    };
    this.registry.saveService({ ...svc, parameters: params });
  }

  /** Toggle hidden flag on a parameter */
  toggleParameterHidden(index: number): void {
    const svc = this.getSelectedService();
    if (!svc) return;

    const params = [...svc.parameters];
    params[index] = { ...params[index], hidden: !params[index].hidden };
    this.registry.saveService({ ...svc, parameters: params });
  }

  /** Toggle required flag on a parameter */
  toggleParameterRequired(index: number): void {
    const svc = this.getSelectedService();
    if (!svc) return;

    const params = [...svc.parameters];
    params[index] = { ...params[index], required: !params[index].required };
    this.registry.saveService({ ...svc, parameters: params });
  }
}
